void AbilityRecord::GrantUriPermission(Want &want, std::string targetBundleName, bool isSandboxApp,
    uint32_t tokenId, bool isNotifyCollaborator)
{
    // only for UIAbility and send result
    if (specifyTokenId_ > 0) {
        TAG_LOGI(AAFwkTag::ABILITYMGR, "specifyTokenId: %{public}u, cleaned", specifyTokenId_);
        tokenId = specifyTokenId_;
        specifyTokenId_ = 0;
    }
    // reject sandbox to grant uri permission by start ability
    auto caller = GetCallerRecord();
    if (caller && AbilityRuntime::GlobalConstant::IsDlpIndex(caller->appIndex_)) {
        TAG_LOGE(AAFwkTag::ABILITYMGR, "DLP sandbox can not grant UriPermission");
        return;
    }
    auto callerTokenId = tokenId > 0 ? tokenId :
        static_cast<uint32_t>(want.GetIntParam(Want::PARAM_RESV_CALLER_TOKEN, 0));
    TAG_LOGD(AAFwkTag::ABILITYMGR, "callerTokenId:%{public}u, tokenId:%{public}u", callerTokenId, tokenId);
    GrantUriPermissionInfo grantInfo;
    grantInfo.callerTokenId = callerTokenId;
    grantInfo.collaboratorType = collaboratorType_;
    grantInfo.isSandboxApp = isSandboxApp;
    grantInfo.appIndex = appIndex_;
    grantInfo.targetBundleName = targetBundleName;
    grantInfo.userId = GetOwnerMissionUserId();
    grantInfo.flag = want.GetFlags();
    grantInfo.isNotifyCollaborator = isNotifyCollaborator;
    grantInfo.targetUid = uid_;
    grantInfo.callerUid = want.GetIntParam(Want::PARAM_RESV_CALLER_UID, IPCSkeleton::GetCallingUid());
    if (!isNotifyCollaborator) {
        grantInfo.targetAbilityName = abilityInfo_.name;
    }
    UriUtils::GetInstance().GrantUriPermission(want, grantInfo);
}

export default class BluetoothServiceAbility extends ShareExtensionAbility {
    private uris: Array<string> = [];
    private isSystemShareOpen: boolean = false; // 标记ability是否被系统分享拉起
    onCreate(launchParam: AbilityConstant.LaunchParam): void {
        if (launchParam.launchReasonMessage === 'ReasonMessage_SystemShare') {
            // 识别为被系统分享拉起
            this.isSystemShareOpen = true;
            console.log(`${TAG} onCreate is called`);
        }
    }

    onDestroy(): void {
        console.log(`${TAG} onDestroy is called`);
    }

    public async onSessionCreate(want: Want, session: UIExtensionContentSession): Promise<void> {
        if (!this.isSystemShareOpen) {
            return;
        }
        console.log(`${TAG} onSessionCreate is called`);
        let systemShareModule = loadNativeModule('@hms:collaboration.systemShare') as ESObject;
        try {
            let data = await systemShareModule.getSharedData(want);
            let records = data.getRecords();
            for (let i = 0; i < records.length; i++) {
                let filePath = '';
                if (records[i].uri == undefined && records[i].content != undefined) {
                    console.log(`${TAG} share txt content`);
                    filePath = this.context.filesDir + '/' + (i + 1) + '.txt';
                    let file = fs.openSync(filePath, fs.OpenMode.READ_WRITE | fs.OpenMode.CREATE);
                    let writeLen = fs.writeSync(file.fd, records[i].content);
                    console.log(`${TAG} write data to file success and size is:` + writeLen);
                    fs.closeSync(file);
                } else if (records[i].uri == undefined) { 
                    console.log(`${TAG} records[i].uri is undefined`);
                } else {
                    filePath = records[i].uri;
                }
                this.uris.push(filePath);
            }
            AppStorage.setOrCreate('sendFileUris', this.uris);
            AppStorage.setOrCreate('sendFileUrisLength', this.uris.length);
        } catch (err) {
            console.log(`${TAG} records fail`);
        }
        let localStorage: LocalStorage = new LocalStorage({
            session: session
        } as UIExtensionStorage);
        try {
            session.loadContent('pages/BluetoothShare', localStorage);
            session.setWindowBackgroundColor('#00000000');
        } catch (err) {
            console.log(`${TAG} loadContent fail`);
        }
    }

    onSessionDestroy(): void {
        console.log(`${TAG} onSessionDestroy is called`);
    }

